/*
    検索グリッド上のイベントアップボタンの制御
*/

/* 
  250728: 選択行のステータスによるメニューボタン有効・無効制御サンプル
  MenuButtonの初期化メソッドを検索グリッド上の行選択で発火させるためには、
  自身のinclude_eventsで「ステートの更新」を有効化するだけでは不足する。

  必ず、親メニューのinclude_eventsでも「ステートの更新」を有効化しておくこと。
*/

//Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;

// 検索グリッドの選択行ステータスによる有効化判定
var selectedRowsCount = options.getState().grid.selectedRows.length;
var disableFlag = true;

if (selectedRowsCount == 1) {
    // 選択行のItemId取得
    var selectedItemId = options.getState().grid.selectedRows[0];
    // 選択行のItem State取得
    var selectedItem = iomInv.newItem(options.itemTypeName, "get");
    selectedItem.setID(selectedItemId);
    selectedItem.setAttribute("select", "state");
    selectedItem = selectedItem.apply();

    var selectedItemState = selectedItem.getProperty("state");

    // ステータスによる有効無効判定(承認、または、仮承認の場合はfalse、それ以外の場合はtrue)
    if (selectedItemState == "Approved" || selectedItemState == "ProvisionalApproved") {
        disableFlag = false;
    }
}

return {disabled: disableFlag};
